function is_undulating(n) {
  if (n.toString().length < 3) return false;

  let is_odd = false;
  let odd_count = 0;
  let even_count = 0;

  for (let i = 1; i < n.toString().length; i++) {
    if (parseInt(n.toString()[i], 10) % 2 !== parseInt(n.toString()[i - 1], 10) % 2) {
      is_odd = !is_odd;
      if (is_odd) odd_count++;
      else even_count++;
    }
  }

  return odd_count === 1 && even_count === 1;
}

