function find_kth(arr1, arr2, k){
    let i = 0, j = 0;
    while (i < arr1.length && j < arr2.length) {
        if (arr1[i] < arr2[j]) {
            k--;
            if (k === 0) return arr1[i];
            i++;
        } else {
            k--;
            if (k === 0) return arr2[j];
            j++;
        }
    }
    while (i < arr1.length) {
        k--;
        if (k === 0) return arr1[i];
        i++;
    }
    while (j < arr2.length) {
        k--;
        if (k === 0) return arr2[j];
        j++;
    }
    throw new Error("k is out of bounds");
}

