function magic_square_test(my_matrix){
    const n = my_matrix.length;
    if (n <= 0) return false;

    // Check if the matrix is square
    for (let i = 1; i < n; i++) {
        if (my_matrix[i].length !== n) return false;
    }

    // Calculate the sum of the first row
    const sum_first_row = my_matrix[0].reduce((acc, val) => acc + val, 0);

    // Check if all rows have the same sum
    for (let i = 1; i < n; i++) {
        if (my_matrix[i].reduce((acc, val) => acc + val, 0) !== sum_first_row) return false;
    }

    // Check if all columns have the same sum
    for (let i = 0; i < n; i++) {
        let col_sum = 0;
        for (let j = 0; j < n; j++) {
            col_sum += my_matrix[j][i];
        }
        if (col_sum !== sum_first_row) return false;
    }

    // Check if the diagonals have the same sum
    let diag_sum1 = 0;
    let diag_sum2 = 0;
    for (let i = 0; i < n; i++) {
        diag_sum1 += my_matrix[i][i];
        diag_sum2 += my_matrix[i][n - 1 - i];
    }
    if (diag_sum1 !== sum_first_row || diag_sum2 !== sum_first_row) return false;

    return true;
}

