function maxAverageOfPath(cost){
  const rows = cost.length;
  const cols = cost[0].length;
  const dp = Array.from({ length: rows }, () => Array(cols).fill(0));

  // Base case: the cost of the first cell
  dp[0][0] = cost[0][0];

  // Fill the first row and first column
  for (let i = 1; i < rows; i++) {
    dp[i][0] = dp[i-1][0] + cost[i][0];
  }
  for (let j = 1; j < cols; j++) {
    dp[0][j] = dp[0][j-1] + cost[0][j];
  }

  // Fill the rest of the dp table
  for (let i = 1; i < rows; i++) {
    for (let j = 1; j < cols; j++) {
      dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]) + cost[i][j];
    }
  }

  // The maximum average path will be the maximum value in the bottom-right cell
  return dp[rows-1][cols-1] / (rows * cols);
}

function maxAverageOfPath(cost){
    const n = cost.length;
    let dp = Array.from({length: n}, () => Array(n).fill(0));

    // Fill the dp table
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (i === 0 && j === 0) {
                dp[i][j] = cost[i][j];
            } else {
                dp[i][j] = cost[i][j] + Math.max(dp[i-1][j], dp[i][j-1]);
            }
        }
    }

    // Find the maximum average path
    let maxAvg = -Infinity;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            let avg = dp[i][j] / (i + j + 1);
            if (avg > maxAvg) {
                maxAvg = avg;
            }
        }
    }

    return maxAvg;
}

