    const len = numStr.length;
    const effectiveShift = shift % len; // Handle shift > number of digits

    if (effectiveShift === 0) {
        return numStr;
    } else if (effectiveShift > len) {
        return numStr.split('').reverse().join('');
    } else {
        const part1 = numStr.substring(len - effectiveShift);
        const part2 = numStr.substring(0, len - effectiveShift);
        return part2 + part1;
    }
}

