function shell_sort(my_list) {
    let n = my_list.length;
    let gap = Math.floor(n / 2);

    while (gap > 0) {
        for (let i = 0; i < n - gap; i++) {
            let j = i;
            while (j >= 0 && my_list[j] > my_list[j + gap]) {
                [my_list[j], my_list[j + gap]] = [my_list[j + gap], my_list[j]];
                j -= gap;
            }
        }
        gap = Math.floor(gap / 2);
    }

    return my_list;
}

