function get_total_number_of_sequences(m, n) {
    // Initialize a 2D array to store the number of sequences for each length and number of previous elements
    const dp = new Array(n + 1).fill(0).map(() => new Array(m + 1).fill(0));

    // Base case: There is only one way to have a sequence of length 0 (the empty sequence)
    dp[0][0] = 1;

    // Fill the DP table
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= m; j++) {
            // If the previous element is less than or equal to twice the current element, we can include it in the sequence
