  for (const num of nums) {
    if (frequencyMap.has(num)) {
      frequencyMap.set(num, frequencyMap.get(num) + 1);
    } else {
      frequencyMap.set(num, 1);
    }
  }

  let maxFrequency = 0;
  let maxOccurrenceItem = null;

  for (const [item, frequency] of frequencyMap) {
    if (frequency > maxFrequency) {
      maxFrequency = frequency;
      maxOccurrenceItem = item;
    }
  }

  return maxOccurrenceItem;
}

function sort_numbers(numbers) {
    const numberWords = {
        zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9
    };

    // Split the input string into an array of words
    const wordsArray = numbers.split(' ');

    // Convert the array of words to an array of numbers using the conversion object
    const numbersArray = wordsArray.map(word => numberWords[word]);

    // Sort the array of numbers
    numbersArray.sort((a, b) => a - b);

    // Convert the sorted array of numbers back to an array of words
    const sortedWordsArray = numbersArray.map(number => Object.keys(numberWords)[number]);

    // Join the sorted array of words back into a string
    const sortedNumbers = sortedWordsArray.join(' ');

    return sortedNumbers;
}

