function get_coordinates(test_tup){
    const [x, y] = test_tup;
    const coordinates = [];

    // Check if there is a coordinate to the left
    if (x > 0) {
        coordinates.push([x - 1, y]);
    }

    // Check if there is a coordinate to the right
    if (x < test_tup.length - 1) {
        coordinates.push([x + 1, y]);
    }

    // Check if there is a coordinate above
    if (y > 0) {
        coordinates.push([x, y - 1]);
    }

    // Check if there is a coordinate below
    if (y < test_tup[0].length - 1) {
        coordinates.push([x, y + 1]);
    }

    return coordinates;
}

function get_coordinates(test_tup) {
    // Initialize an array to store the adjacent coordinates
    const adjacent_coords = [];

    // Iterate over each coordinate in the test_tup
    for (let i = 0; i < test_tup.length; i++) {
        // Check if the current coordinate has a left neighbor
        if (i > 0) {
            adjacent_coords.push([test_tup[i - 1][0], test_tup[i - 1][1]]);
        }

        // Check if the current coordinate has a right neighbor
        if (i < test_tup.length - 1) {
            adjacent_coords.push([test_tup[i + 1][0], test_tup[i + 1][1]]);
        }
    }

    return adjacent_coords;
}

