function lcs_of_three(X, Y, Z){
    let m = X.length;
    let n = Y.length;
    let p = Z.length;

    // Create a 3D array to store lengths of LCSes
    let dp = Array.from({ length: m + 1 }, () => Array.from({ length: n + 1 }, () => Array.from({ length: p + 1 }, () => 0)));

    // Build the dp array in bottom-up manner
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            for (let k = 1; k <= p; k++) {
                if (X[i - 1] === Y[j - 1] && Y[j - 1] === Z[k - 1]) {
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1;
                } else {
                    dp[i][j][k] = Math.max(dp[i - 1][j][k], dp[i][j - 1][k], dp[i][j][k - 1]);
                }
            }
        }
    }

    // The length of the longest common subsequence of X, Y, and Z
    return dp[m][n][p];
}

