function search(lst){
  const frequencyMap = {};
  let maxFrequency = 0;

  // Count the frequency of each number
  lst.forEach(num => {
    if (frequencyMap[num]) {
      frequencyMap[num]++;
    } else {
      frequencyMap[num] = 1;
    }
  });

  // Find the greatest number with a frequency greater than or equal to the value of the number itself
  for (const key in frequencyMap) {
    if (parseInt(key) <= frequencyMap[key]) {
      maxFrequency = Math.max(maxFrequency, parseInt(key));
    }
  }

  // Return -1 if no such number exists
  return maxFrequency === 0 ? -1 : maxFrequency;
}

function find_combinations(test_list) {
  const result = [];

  function backtrack(start, currentSum, path) {
    if (currentSum === 0) {
      result.push([...path]);
      return;
    }

    for (let i = start; i < test_list.length; i++) {
      if (test_list[i] > currentSum) break;
      backtrack(i + 1, currentSum - test_list[i], [...path, test_list[i]]);
    }
  }

  backtrack(0, 0, []);
  return result;
}

function find_combinations(test_list) {
  const combinations = [];

  function generateCombinations(arr, index, currentSum, currentCombination) {
    if (currentSum === test_list[index]) {
      combinations.push([...currentCombination]);
      return;
    }
    if (currentSum > test_list[index]) {
      return;
    }

    for (let i = index; i < arr.length; i++) {
      currentCombination.push(arr[i]);
      generateCombinations(arr, i + 1, currentSum + arr[i], currentCombination);
      currentCombination.pop();
    }
  }

  generateCombinations(test_list, 0, 0, []);
  return combinations;
}

