function max_sum(arr) {
  let n = arr.length;
  let dp = Array.from({ length: n }, () => Array(n).fill(0));

  // Initialize the table
  for (let i = 0; i < n; i++) {
    dp[i][i] = arr[i];
  }

  // Fill dp table
  for (let len = 2; len <= n; len++) {
    for (let start = 0; start <= n - len; start++) {
      let end = start + len - 1;
      for (let i = start + 1; i <= end; i++) {
        if (arr[i] > arr[start] && arr[i] > arr[end]) {
          dp[start][end] = Math.max(dp[start][end], dp[start][i] + dp[i][end]);
        }
      }
    }
  }

  // Find the maximum sum of bitonic subsequence
  let max_sum = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      max_sum = Math.max(max_sum, dp[i][j]);
    }
  }

  return max_sum;
}

function max_sum(arr){
    let n = arr.length;
    let max = new Array(n);
    let min = new Array(n);

    // Fill max table
    for (let i = 0; i < n; i++) {
        max[i] = arr[i];
        for (let j = 0; j < i; j++) {
            if (arr[j] < arr[i] && max[i] < max[j] + arr[i]) {
                max[i] = max[j] + arr[i];
            }
        }
    }

    // Fill min table
    for (let i = n - 1; i >= 0; i--) {
        min[i] = arr[i];
        for (let j = n - 1; j > i; j--) {
            if (arr[j] < arr[i] && min[i] < min[j] + arr[i]) {
                min[i] = min[j] + arr[i];
            }
        }
    }

    // Find maximum sum of bitonic subsequence
    let ans = 0;
    for (let i = 0; i < n; i++) {
        ans = Math.max(ans, max[i] + min[i] - arr[i]);
    }

    return ans;
}

