  }
  return string;
}

function make_palindrome(string) {
    if (string === "") return "";

    let len = string.length;
    let left = 0, right = len - 1;
    while (left < right) {
        if (string[left] !== string[right]) {
            break;
        }
        left++;
        right--;
    }
    if (left === right) {
        return string;
    }

    let postfix = string.slice(left);
    let prefix = string.slice(0, len - left);
    let reversedPrefix = prefix.split('').reverse().join('');

    return postfix + reversedPrefix;
}

