function by_length(arr){
  if (arr.length === 0) return [];

  const numbers = arr.filter(num => num >= 1 && num <= 9).reverse();
  const names = numbers.map(num => {
    switch (num) {
      case 1: return "One";
      case 2: return "Two";
      case 3: return "Three";
      case 4: return "Four";
      case 5: return "Five";
      case 6: return "Six";
      case 7: return "Seven";
      case 8: return "Eight";
      case 9: return "Nine";
      default: return "";
    }
  });

  return names;
}

function by_length(arr) {
  const numbersToNames = {
    1: 'One', 2: 'Two', 3: 'Three', 4: 'Four', 5: 'Five', 6: 'Six', 7: 'Seven', 8: 'Eight', 9: 'Nine'
  };
  const validNumbers = arr.filter(num => num >= 1 && num <= 9).sort((a, b) => b - a);
  return validNumbers.map(num => numbersToNames[num]);
}

function even_odd_count(num){
  let evenCount = 0;
  let oddCount = 0;
  num = Math.abs(num); // Remove any negative sign
  while(num > 0){
    let digit = num % 10;
    if(digit % 2 === 0){
      evenCount++;
    } else {
      oddCount++;
    }
    num = Math.floor(num / 10);
  }
  return [evenCount, oddCount];
}

function even_odd_count(num) {
  const digits = Math.abs(num).toString().split('');
  let evenCount = 0;
  let oddCount = 0;

  for (const digit of digits) {
    if (parseInt(digit) % 2 === 0) {
      evenCount++;
    } else {
      oddCount++;
    }
  }

  return [evenCount, oddCount];
}

function order_by_points(nums){
  return nums.sort((a, b) => {
    const sumA = a.toString().split('').reduce((acc, digit) => acc + parseInt(digit), 0);
    const sumB = b.toString().split('').reduce((acc, digit) => acc + parseInt(digit), 0);
    if (sumA === sumB) {
      return nums.indexOf(a) - nums.indexOf(b);
    }
    return sumA - sumB;
  });
}

