function list_split(S, step){
  return S.reduce((acc, el, idx) => {
    if ((idx + 1) % step === 0) {
      acc.push(S.slice(idx));
    }
    return acc;
  }, []);
}

function list_split(S, step) {
  return S.reduce((acc, curr, index) => {
    if ((index + 1) % step === 0) {
      acc.push([curr]);
    } else {
      acc[acc.length - 1].push(curr);
    }
    return acc;
  }, []);
}

//Write a function to check whether the given number is undulating or not.
function is_undulating(n){
    if(n.toString().length < 3) return false;

    let increasing = true;
    let decreasing = true;

    for(let i = 1; i < n.toString().length; i++){
        if(n.toString()[i] > n.toString()[i-1]) decreasing = false;
        if(n.toString()[i] < n.toString()[i-1]) increasing = false;
    }

    return increasing || decreasing;
}

function is_undulating(n){
  if (n < 2) return false;
  let even = true;
  let odd = true;
  for (let i = 1; i < n.toString().length; i++) {
    if (i % 2 === 0 && parseInt(n.toString()[i]) > parseInt(n.toString()[i - 1])) {
      even = false;
    } else if (i % 2 !== 0 && parseInt(n.toString()[i]) < parseInt(n.toString()[i - 1])) {
      odd = false;
    }
  }
  return even || odd;
}

function sum_Of_product(n) {
  let sum = 0;
  for (let i = 0; i < n; i++) {
    sum += Math.pow(2, i) * Math.pow(2, n - i - 1);
  }
  return sum;
}

function sum_Of_product(n) {
  let sum = 0;
  for (let i = 0; i <= n; i++) {
    sum += Math.pow(2, i) * (n - i);
  }
  return sum;
}

function bell_number(n) {
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let nextBell = 0;
    for (let j = 0; j < i; j++) {
      nextBell += bell[j] * bell[i - j - 1];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

function bell_number(n){
  if(n === 0) return 1;
  let bell = [1];
  for(let i = 1; i <= n; i++){
    let temp = 0;
    for(let j = 0; j < i; j++){
      temp += bell[j] * bell[i - j - 1];
    }
    bell.push(temp);
  }
  return bell[n];
}

function get_max_sum(n) {
  if (n <= 1) return n;

  let maxSum = n;
  let half = Math.floor(n / 2);
  let third = Math.floor(n / 3);
  let fourth = Math.floor(n / 4);
  let fifth = Math.floor(n / 5);

  maxSum = Math.max(maxSum, get_max_sum(half) + get_max_sum(third) + get_max_sum(fourth) + get_max_sum(fifth));

  return maxSum;
}

function extract_even(test_tuple){
  return test_tuple.reduce((acc, item) => {
    if(Array.isArray(item)) {
      acc.push(...extract_even(item));
    } else if(item % 2 === 0) {
      acc.push(item);
    }
    return acc;
  }, []);
}

function extract_even(test_tuple){
