  let sum = 0;
  for(let i = 0; i <= n; i++){
    if(i % 2 === 0){
      sum += Math.pow(2, i);
    }
  }
  return sum;
}

function even_binomial_Coeff_Sum(n) {
    let sum = 0;
    for (let i = 0; i <= n; i += 2) {
        sum += binomialCoefficient(n, i);
    }
    return sum;
}

function binomialCoefficient(n, k) {
    if (k > n - k) {
        k = n - k;
    }
    let result = 1;
    for (let i = 1; i <= k; i++) {
        result = result * (n - k + i) / i;
    }
    return result;
}

