function is_multiply_prime(a){
  if (a < 2) return false;
  let primeCount = 0;

  for (let i = 2; i <= Math.sqrt(a); i++) {
    if (a % i === 0) {
      primeCount++;
      if (primeCount > 3) return false;
    }
  }

  return primeCount === 3;
}

function is_multiply_prime(a){
  let count = 0;
  for(let i=2; i<=a; i++){
    if(a%i === 0){
      if(isPrime(i)){
        count++;
        if(count > 3){
          return false;
        }
      }
    }
  }
  return count === 3;
}

function isPrime(num){
  if(num <= 1) return false;
  for(let i=2; i*i<=num; i++){
    if(num%i === 0) return false;
  }
  return true;
}

