function sorted_list_sum(lst){
  // Filter out strings with odd lengths
  const evenLengths = lst.filter(word => word.length % 2 === 0);

  // Sort the array by length and then alphabetically
  evenLengths.sort((a, b) => a.length - b.length || a.localeCompare(b));

  return evenLengths;
}

